CREATE OR REPLACE FUNCTION public._notification_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner_id uuid; BEGIN CASE TG_TABLE_NAME WHEN 'nudges' THEN PERFORM _notify(NEW.to_user,'nudge',NEW.crew_id::text||':'||NEW.day::text,'/community'); WHEN 'buddy_requests' THEN IF NEW.status='pending' THEN PERFORM _notify(NEW.to_user,'buddy',NEW.id::text,'/buddies'); END IF; WHEN 'post_reactions' THEN SELECT user_id INTO owner_id FROM posts WHERE id=NEW.post_id AND NOT hidden; IF owner_id IS NOT NULL AND owner_id<>NEW.user_id THEN PERFORM _notify(owner_id,'reaction',NEW.post_id::text||':'||NEW.user_id::text,'/community'); END IF; WHEN 'daily_scores' THEN IF NEW.crew_sync THEN PERFORM _notify(NEW.user_id,'crew',NEW.season_id::text||':'||NEW.day::text,'/community'); END IF; ELSE NULL; END CASE; RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public._notification_event() FROM PUBLIC,anon,authenticated;